import re
from fractions import Fraction


def fraction_expr(s: str) -> str:
    if not isinstance(s, str):
        raise ValueError("input must be a string")

    # ---------- tokenizer ----------
    tok_re = re.compile(r'\d+/\d+|\d+|[()+\-*]')
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue
        m = tok_re.match(s, i)
        if not m:
            raise ValueError("bad character %r at %d" % (c, i))
        tokens.append(m.group(0))
        i = m.end()

    if not tokens:
        raise ValueError("empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("unexpected end of expression")
        pos += 1
        return t

    # ---------- parser ----------
    # expr   := term (('+'|'-') term)*
    # term   := factor ('*' factor)*
    # factor := '-' factor | '+' factor | '(' expr ')' | number
    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            val = val + rhs if op == '+' else val - rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek() == '*':
            advance()
            val = val * parse_factor()
        return val

    def parse_factor():
        t = peek()
        if t is None:
            raise ValueError("unexpected end of expression")
        if t == '-':
            advance()
            return -parse_factor()
        if t == '+':
            advance()
            return parse_factor()
        if t == '(':
            advance()
            val = parse_expr()
            if peek() != ')':
                raise ValueError("missing closing parenthesis")
            advance()
            return val
        if t in (')', '*'):
            raise ValueError("unexpected token %r" % t)
        # numeric literal
        advance()
        if '/' in t:
            num_s, den_s = t.split('/', 1)
            if not num_s.isdigit() or not den_s.isdigit():
                raise ValueError("malformed fraction %r" % t)
            den = int(den_s)
            if den == 0:
                raise ValueError("zero denominator")
            return Fraction(int(num_s), den)
        if not t.isdigit():
            raise ValueError("malformed number %r" % t)
        return Fraction(int(t), 1)

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("unexpected token %r" % tokens[pos])

    # ---------- formatting ----------
    num, den = result.numerator, result.denominator
    if den < 0:  # Fraction normalizes, but be safe
        num, den = -num, -den
    if num == 0:
        return '0'
    if den == 1:
        return str(num)
    return "%d/%d" % (num, den)
```

The tokenizer accepts tokens whether or not parentheses are space-separated; the recursive-descent parser handles unary minus at any factor position, and any leftover or unexpected token, empty input, or zero denominator raises `ValueError`.
